KEYS = {'sstv_adjust_image': {'en': 'Adjust received image', 'it': 'Regola immagine ricevuta', 'fr': 'Ajuster l’image reçue', 'de': 'Empfangenes Bild anpassen', 'no': 'Juster mottatt bilde', 'cs': 'Upravit přijatý obraz'}, 'sstv_clear_adjust': {'en': 'Reset adjustments', 'it': 'Azzera regolazioni', 'fr': 'Réinitialiser les réglages', 'de': 'Anpassungen zurücksetzen', 'no': 'Nullstill justeringer', 'cs': 'Vynulovat úpravy'}, 'sstv_start_free_run': {'en': 'Start RX without synchronization', 'it': 'Avvia RX senza sincronismo', 'fr': 'Démarrer RX sans synchronisation', 'de': 'RX ohne Synchronisation starten', 'no': 'Start RX uten synkronisering', 'cs': 'Spustit RX bez synchronizace'}, 'sstv_free_run_help': {'en': 'Restarts the image and disables VIS and line sync.', 'it': 'Riavvia l’immagine e disattiva VIS e sincronismo delle righe.', 'fr': 'Redémarre l’image et désactive VIS et la synchronisation des lignes.', 'de': 'Startet das Bild neu und schaltet VIS und Zeilensynchronisierung ab.', 'no': 'Starter bildet på nytt og slår av VIS og linjesynkronisering.', 'cs': 'Znovu spustí obraz a vypne VIS i synchronizaci řádků.'}, 'sstv_horizontal_position': {'en': 'Horizontal position', 'it': 'Posizione orizzontale', 'fr': 'Position horizontale', 'de': 'Horizontale Position', 'no': 'Vannrett posisjon', 'cs': 'Vodorovná poloha'}, 'sstv_red_alignment': {'en': 'Red alignment', 'it': 'Allineamento rosso', 'fr': 'Alignement rouge', 'de': 'Rot ausrichten', 'no': 'Rød justering', 'cs': 'Zarovnání červené'}, 'sstv_blue_alignment': {'en': 'Blue alignment', 'it': 'Allineamento blu', 'fr': 'Alignement bleu', 'de': 'Blau ausrichten', 'no': 'Blå justering', 'cs': 'Zarovnání modré'}, 'sstv_adjust_phase_help': {'en': 'Moves all received rows horizontally, including a completed image. Positive values move right. Returning to zero restores the original phase.', 'it': 'Sposta orizzontalmente tutte le righe ricevute, anche a immagine completa. I valori positivi spostano a destra. Tornando a zero si ripristina la fase originale.', 'fr': 'Déplace horizontalement toutes les lignes reçues, même après la fin de l’image. Les valeurs positives déplacent vers la droite. Zéro rétablit la phase d’origine.', 'de': 'Verschiebt alle empfangenen Zeilen, auch nach Bildabschluss. Positive Werte verschieben nach rechts. Null stellt die ursprüngliche Phase wieder her.', 'no': 'Flytter alle mottatte linjer vannrett, også når bildet er ferdig. Positive verdier flytter mot høyre. Null gjenoppretter opprinnelig fase.', 'cs': 'Posune vodorovně všechny přijaté řádky i po dokončení obrazu. Kladné hodnoty posouvají doprava. Nula obnoví původní fázi.'}, 'sstv_adjust_red_help': {'en': 'Aligns red against green across the received image. Returning to zero restores the original red channel.', 'it': 'Allinea il rosso rispetto al verde su tutta l’immagine ricevuta. Tornando a zero si ripristina il canale rosso originale.', 'fr': 'Aligne le rouge sur le vert dans toute l’image reçue. Zéro rétablit le canal rouge d’origine.', 'de': 'Richtet Rot im gesamten Empfangsbild an Grün aus. Null stellt den ursprünglichen Rotkanal wieder her.', 'no': 'Justerer rødt mot grønt i hele det mottatte bildet. Null gjenoppretter opprinnelig rødkanal.', 'cs': 'Zarovná červenou vůči zelené v celém přijatém obrazu. Nula obnoví původní červený kanál.'}, 'sstv_adjust_blue_help': {'en': 'Aligns blue against green across the received image. Returning to zero restores the original blue channel.', 'it': 'Allinea il blu rispetto al verde su tutta l’immagine ricevuta. Tornando a zero si ripristina il canale blu originale.', 'fr': 'Aligne le bleu sur le vert dans toute l’image reçue. Zéro rétablit le canal bleu d’origine.', 'de': 'Richtet Blau im gesamten Empfangsbild an Grün aus. Null stellt den ursprünglichen Blaukanal wieder her.', 'no': 'Justerer blått mot grønt i hele det mottatte bildet. Null gjenoppretter opprinnelig blåkanal.', 'cs': 'Zarovná modrou vůči zelené v celém přijatém obrazu. Nula obnoví původní modrý kanál.'}}
HELP = {'en': ('Adjust a received SSTV image', 'Open Adjust received image in the Mode tab. Horizontal position rolls the image; Red alignment and Blue alignment register those channels against green. Every change redraws all received rows, during reception and after completion, including Robot and PD. Reset adjustments restores the original received pixels. Saving PNG uses the corrected image. The collapsed panel leaves ordinary RX controls compact. Start RX without synchronization explicitly restarts the image and disables both VIS and line sync; re-enable the two checkboxes for automatic reception.'), 'it': ('Regolare un’immagine SSTV ricevuta', 'Apri Regola immagine ricevuta nella scheda Modo. Posizione orizzontale fa scorrere l’immagine; Allineamento rosso e Allineamento blu registrano i due canali rispetto al verde. Ogni modifica ridisegna tutte le righe ricevute, durante la ricezione e a immagine completata, anche in Robot e PD. Azzera regolazioni ripristina i pixel ricevuti originali. Salva PNG usa l’immagine corretta. Il pannello richiudibile mantiene compatti i normali comandi RX. Avvia RX senza sincronismo riavvia esplicitamente l’immagine e disattiva sia VIS sia sincronismo delle righe; riattiva le due caselle per tornare alla ricezione automatica.'), 'fr': ('Ajuster une image SSTV reçue', 'Ouvrez Ajuster l’image reçue dans l’onglet Mode. Position horizontale fait défiler l’image ; Alignement rouge et bleu règlent les canaux par rapport au vert. Chaque modification redessine toutes les lignes reçues, pendant et après la réception, y compris Robot et PD. Réinitialiser rétablit les pixels reçus d’origine. Le PNG enregistré utilise l’image corrigée. Le panneau se replie. Démarrer RX sans synchronisation redémarre l’image et désactive VIS et la synchronisation des lignes ; réactivez les deux cases pour la réception automatique.'), 'de': ('Ein empfangenes SSTV-Bild anpassen', 'Im Modus-Reiter Empfangenes Bild anpassen öffnen. Horizontale Position rollt das Bild; Rot und Blau werden relativ zu Grün ausgerichtet. Jede Änderung zeichnet alle empfangenen Zeilen neu, während und nach dem Empfang, auch bei Robot und PD. Anpassungen zurücksetzen stellt die ursprünglichen Empfangspixel wieder her. PNG speichert das korrigierte Bild. Das Bedienfeld lässt sich einklappen. RX ohne Synchronisation starten beginnt das Bild neu und schaltet VIS und Zeilensynchronisierung ab; beide Kontrollkästchen für automatischen Empfang wieder einschalten.'), 'no': ('Justere et mottatt SSTV-bilde', 'Åpne Juster mottatt bilde i Modus-fanen. Vannrett posisjon ruller bildet; rødt og blått justeres mot grønt. Hver endring tegner alle mottatte linjer på nytt, under og etter mottak, også Robot og PD. Nullstill justeringer gjenoppretter de opprinnelige mottatte pikslene. PNG lagrer det korrigerte bildet. Panelet kan foldes sammen. Start RX uten synkronisering starter bildet på nytt og slår av både VIS og linjesynkronisering; slå på begge avkrysningsboksene igjen for automatisk mottak.'), 'cs': ('Upravit přijatý obraz SSTV', 'Na kartě Režim otevřete Upravit přijatý obraz. Vodorovná poloha posouvá obraz; červená a modrá se zarovnávají vůči zelené. Každá změna překreslí všechny přijaté řádky během příjmu i po dokončení, také u Robot a PD. Vynulovat úpravy obnoví původní přijaté pixely. PNG ukládá opravený obraz. Panel lze sbalit. Spustit RX bez synchronizace restartuje obraz a vypne VIS i synchronizaci řádků; pro automatický příjem znovu zapněte obě políčka.')}
